INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('tunisian','Tunisian','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"tunisian","name":"Tunisian","team":"townsfolk","ability":"Twice per game, choose a player (not yourself): the latest chosen is drunk if Outsider or Minion & cannot die at night if allied.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-244 is a Tunisian jar that constantly disperses a fog of pure cold air that cools down the body to it''s core.","summaryBullets":["The Tunisian makes the chosen Outsiders and Minions drunk and protects the chosen allies during the night.","Whilst the Tunisian can make their choice at any time during the game, they also privately wake up at night to make their choices silently if they so wish.","Both effects can occur at once, including Outsiders but irregularly on a good Minion.","The Tunisian''s protection for allied players is similar to the Innkeeper in which it makes players not just safe from being killed by the Demon, but also from death caused by Outsiders, Minions, Townsfolk, and Travellers.","The Tunisian only protects chosen allied players at night, not the day.","Whilst the Tunisian only has two uses of their ability, the effects they impose on their latest chosen player are not limited to just that night and upcoming day.","If the latest chosen player changes character or alignment, the effects imposed by the Tunisian will update accordingly."],"howToRun":["At any time during the game, the Tunisian may choose a player, either publicly or by having a private discussion with you. Each night, wake the Tunisian in-case they want to make their choice during the night privately. They either shake their head no or point at any player except themselves {{i|(If the Tunisian points at themselves, shake your head no and prompt them to point at another player.)}} Put the Tunisian to sleep.","If the Tunisian chose a player, mark them with the **CHOSEN** reminder. If a player was already marked with the **CHOSEN** reminder token, instead move it onto the new player chosen. **The Tunisian loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **ABILITY USED** reminder and remove their night token from the night sheet {{i|(the Tunisian won''t wake again.)}}","Players marked with the Tunisian''s **CHOSEN** reminder token on the same team as them cannot die at night, and Outsiders or Minions marked with it are **drunk**."],"quote":"يبدو أنك تُعاني. استسلم، سينتهي كل شيء قريبًا!","iconBy":"le_nuberto","jinxes":[{"name":"Leviathan","align":"evil","text":"If Leviathan nominates and executes a player the Tunisian chose, that player does not die.","id":"leviathan"},{"name":"Monk","align":"good","text":"If the Tunisian and Monk are both protecting each other, their abilities to protect against death by the Demon will fail.","id":"monk"},{"name":"Riot","align":"evil","text":"If a Riot player nominates a Tunisian-protected-allied-player, that player does not die.","id":"riot"},{"name":"Summoner","align":"evil","text":"If the the Tunisian has the Summoner drunk on the 3rd night, the Summoner chooses which Demon, but the Storyteller chooses which player.","id":"summoner"},{"name":"Tea Lady","align":"good","text":"If the Tunisian and Tea Lady are both protecting each other, their abilities to protect against death during the night will fail.","id":"tealady"},{"name":"Vizier","align":"evil","text":"If the Vizier loses their ability, they learn this. If the Vizier is executed while they have their ability, their team wins.","id":"vizier"},{"name":"Ketos","align":"evil","text":"If Ketos correctly guesses a Tunisian-protected-player, the end does not come sooner.","id":"ketos_the_bootleggers_anthology"},{"name":"Matsuraid","align":"evil","text":"If the Matsuraid is in play, votes for the the Tunisian-protected player secretly do not count.","id":"matsuraid_hblreleased"},{"name":"Mycologist","align":"good","text":"If the Tunisian and Mycologist are both protecting each other, their abilities to protect against death during the night will fail.","id":"mycologist_hblreleased"},{"name":"Harbormaster","align":"good","text":"If the Tunisian and Harbormaster are both protecting each other, their abilities to protect against death by evil players will fail.","id":"harbormaster_the_mistfits"},{"name":"Medic","align":"good","text":"If the Tunisian and Medic are both protecting each other, their abilities to protect against death will fail.","id":"medic"}],"firstNight":19.244,"otherNight":11.244,"reminders":["Chosen","1 use","Ability used"],"setup":false,"firstNightReminder":"If the Tunisian has not yet fully used their ability: the Tunisian either shows the ''no'' head signal, or points to a player not themself. The latest chosen player is drunk if they''re a Outsider or Minion & is protected at night if they''re on the same team as the Tunisian.","otherNightReminder":"If the Tunisian has not yet fully used their ability: the Tunisian either shows the ''no'' head signal, or points to a player not themself. The latest chosen player is drunk if they''re a Outsider or Minion & is protected at night if they''re on the same team as the Tunisian.","art":"art/tunisian.png","jsonId":"tunisian_scp_fragmented_veil","curata":false}','scp-fragmented-veil/tunisian','published',datetime('now'),datetime('now')),
('neglected','Neglected','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"neglected","name":"Neglected","team":"townsfolk","ability":"Each night, choose a player (not yourself): the 1st other player choosing them with their ability tonight is drunk until dusk.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-268 is a threaded cap that causes the wearer to be in-perceivable the longer they don it on their head.","summaryBullets":["Each night, the first time a player wakes to use their ability and chooses the player the Neglected, chose that player becomes drunk immediately. Their ability does not work tonight, nor the next day.","Later on the same night, if another player wakes to use their ability and chooses the player the Neglected chose, their ability works as normal.","The Neglected cannot make a player drunk unless the player chose the player they chose."],"howToRun":["Each night, wake the Neglected. The Neglected points at any player except themselves. Put the Neglected to sleep. Put the Neglected''s **INVISIBLE** reminder token by the chosen player''s character token.","At night, if a player chooses to use their ability on the player marked with the **INVISIBLE** reminder token, that player immediately becomes **drunk** - mark them with the **DRUNK** reminder and remove the **INVISIBLE** reminder token. Finish resolving this player’s ability and put them to sleep.","At dawn, remove the **INVISIBLE** reminder {{i|(if it''s present)}}.","At dusk, remove the **DRUNK** reminder {{i|(if it''s present)}}."],"quote":"Now you see me...","jinxes":[{"name":"Monk","align":"good","text":"If the Neglected and Monk are both protecting each other, their abilities to protect against death by the Demon will fail.","id":"monk"},{"name":"Summoner","align":"evil","text":"If the Summoner chooses a Neglected-chosen player, the Storyteller chooses which player the Demon will be instead.","id":"summoner"},{"name":"Tea Lady","align":"good","text":"If the Neglected and Tea Lady are both protecting each other, their abilities to protect against death during the night will fail.","id":"tealady"},{"name":"Tunisian","align":"good","text":"If the Neglected and Tunisian are both protecting each other, their abilities to protect against death will fail.","slug":"tunisian"},{"name":"Mycologist","align":"good","text":"If the Neglected and Mycologist are both protecting each other, their abilities to protect against death during the night will fail.","id":"mycologist_hblreleased"},{"name":"Harbormaster","align":"good","text":"If the Neglected and Harbormaster are both protecting each other, their abilities to protect against death by evil players will fail.","id":"harbormaster_the_mistfits"},{"name":"Medic","align":"good","text":"If the Neglected and Medic are both protecting each other, their abilities to protect against death will fail.","id":"medic"}],"customBoxes":[{"title":"Credit","content":"Image: @le_nuberto"},{"title":"Alternative JSON & How to Run","content":"If you feel like using the Neglected should have more drunkening power and ability prevention, albeit being more overpowered, use this JSON. This powerscaled ability is subjective to keeping depending on the script, but is most recommended if there are a lot of choosing player abilities on the script.\n\nEach night, wake the Neglected. The Neglected points at any player except themselves. Put the Neglected to sleep. Put the Neglected''s INVISIBLE reminder token by the chosen player''s character token.\n\nAt night, if a player chooses to use their ability on the player marked with the INVISIBLE reminder token, that player immediately becomes drunk - mark them with the DRUNK reminder reminder token. Finish resolving this player’s ability and put them to sleep.\n\nAt dawn, remove the INVISIBLE reminder.\n\nAt dusk, remove all DRUNK reminders.\n\n**Neglected █~** (Townsfolk)\nEach night, choose a player (not yourself): other players choosing them with their ability tonight is drunk until dusk.\n\n**First night:** The Neglected points to a player not themself. Mark that player ''Invisible''.\n**Other nights:** The previous chosen player is relieved of your effects. The Neglected points to a player not themself. Mark that player ''Invisible''.\n**Reminders:** Invisible, Drunk, Drunk, Drunk, Drunk, Drunk\n**Credit:** Image: @le_nuberto\n\n**Jinxes:**\nMonk: If the Neglected and Monk are both protecting each other, their abilities to protect against death by the Demon will fail.\nSummoner: If the Summoner chooses a Neglected-chosen player, the Storyteller chooses which player the Demon will be instead.\nTea Lady: If the Neglected and Tea Lady are both protecting each other, their abilities to protect against death during the night will fail.\nTunisian: If the Neglected and Tunisian are both protecting each other, their abilities to protect against death will fail.\nMycologist: If the Neglected and Mycologist are both protecting each other, their abilities to protect against death during the night will fail.\nHarbormaster: If the Neglected and Harbormaster are both protecting each other, their abilities to protect against death by evil players will fail.\nMedic: If the Neglected and Medic are both protecting each other, their abilities to protect against death will fail."}],"firstNight":10.268,"otherNight":10.268,"reminders":["Invisible","Drunk"],"setup":false,"firstNightReminder":"The Neglected points to a player not themself. Mark that player ''Invisible''.","otherNightReminder":"The previous chosen player is relieved of your effects. The Neglected points to a player not themself. Mark that player ''Invisible''.","art":"art/neglected.png","jsonId":"neglected_scp_fragmented_veil","curata":false}','scp-fragmented-veil/neglected','published',datetime('now'),datetime('now')),
('panacea','Panacea','townsfolk','le_nuberto',NULL,'','SCP Fragmented Veil','{"slug":"panacea","name":"Panacea","team":"townsfolk","ability":"Twice per game, at night, choose a player: they are safe from everything until dusk.","creator":"le_nuberto","appearsIn":"SCP Fragmented Veil","lede":"The Panacea (SCP-500) is a limited-quantity \"cure-all\" pill - and when it means \"cure-all\", it really, really means cure-all.","summaryBullets":["Twice per game at night, the Panacea can choose to make someone immensely better.","The Panacea may even choose themselves if they so wish.","The chosen patient will be safe from death, drunkenness, poisoning, having their information being overwritten, being redirected onto another target with their ability, being registered as evil to certain abilities {{i|(context-sensitive)}}, being converted to the evil team, and all other sorts of negative actions or effects.","Despite the power and versatility this protection brings as a whole, it still won''t be able to protect against Assassin-like kills."],"howToRun":["Each night, wake the Panacea. They either shake their head no or point at any player. Put the Panacea to sleep.","If the Panacea chose a player, put the Panacea''s **ULTRA-SAFE** reminder token by the chosen player''s character token.","If any player attacks, drunkens, poisons, overwrites info of, imposes a negative effect, redirects the target(s) of, or would register as evil to certain abilities {{i|(context-sensitive)}}, converts the alignment of, or does any negative action/effect to the player marked **ULTRA-SAFE**, the player remains unaffected by the action. Regardless of how many actions were prevented, **the Panacea loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **NO ABILITY** reminder and remove their night token from the night sheet.","At dusk, remove the **ULTRA-SAFE** reminder token."],"tips":["Characters may have funky interactions with the Panacea based off intent, drawback, and merit of their ability. If push comes to shove, remind players to consult on particular character interactions, and how you would rule for the current game. Once you do making a ruling, stick to it like butter and glue!"],"quote":"A panacea is something we’re in dire need of. Find out how to make more of these immediately. -O5-4","iconBy":"le_nuberto","jinxes":[{"name":"Matsuraid","align":"evil","text":"If the Matsuraid is in play, votes for the the Panacea-protected player secretly do not count.","id":"matsuraid_hblreleased"},{"name":"Ketos","align":"evil","text":"If Ketos correctly guesses the Panacea-protected-player, the end does not come sooner.","id":"ketos_the_bootleggers_anthology"},{"name":"Cleric","align":"good","text":"The Panacea cannot protect the Cleric against their own self-inflicted drunkenness.","id":"cleric_circus_music"},{"name":"Corsair","align":"good","text":"The Panacea cannot protect the Corsair against their own self-inflicted drunkenness.","id":"corsair_hypers_hoard_of_homebrew"}],"customBoxes":[{"title":"Credit","content":"Ability: @le_nuberto. Image: @le_nuberto. Help: @supergdpwyl"},{"title":"In the almanac JSON","content":"**First night:** The Panacea either shows the ''no'' head signal, or points to a player. Mark that player ''Ultra-Safe''."},{"title":"Alternative JSON (Older)","content":"If you want to prevent the execution survival aspect of this character and cancel out the protection during the day, use this JSON. Recommended if your script doesn''t support execution survival.\n\n**Panacea █-** (Townsfolk)\nTwice per game, at night, choose a player: they are safe from everything tonight.\n\n**First night:** The Panacea either shows the ''no'' head signal, or points to a player. Mark that player ''Ultra-Safe''.\n**Other nights:** If the Panacea has not yet fully used their ability: the Panacea either shows the ''no'' head signal, or points to a player. Mark that player ''Ultra-Safe''.\n**Reminders:** Ultra-Safe, 1 use, No ability\n**Credit:** Ability: @le_nuberto. Image: @le_nuberto. Help: @supergdpwyl\n\n**Jinxes:**\nMatsuraid: If the Matsuraid is in play, votes for the the Panacea-protected player secretly do not count.\nKetos: If Ketos correctly guesses the Panacea-protected-player, the end does not come sooner.\nCorsair: The Panacea cannot protect the Corsair against their own self-inflicted drunkenness."}],"firstNight":0,"otherNight":10.5,"reminders":["Ultra-Safe","1 use","No ability"],"setup":false,"otherNightReminder":"The previously protected player is no longer protected. If the Panacea has not yet fully used their ability: the Panacea either shows the ''no'' head signal, or points to a player. Mark that player ''Ultra-Safe''.","art":"art/panacea.png","jsonId":"panacea_scp_fragmented_veil","curata":false}','scp-fragmented-veil/panacea','published',datetime('now'),datetime('now')),
('basement-cat','Basement Cat','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"basement-cat","name":"Basement Cat","team":"townsfolk","ability":"Other Townsfolk keep their ability until dusk (or think they do otherwise.)","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-511 are mutant basement cats. Anomalously, their 9 lives superstition seems to manifested into reality.","summaryBullets":["With the Basement Cat active, the deaths of their teammate''s abilities are delayed until the upcoming dusk.","With the Basement Cat on the script, all Townsfolk are expected to keep their ability until dusk. However, should the Basement Cat be dead, or their ability is no longer active {{i|(like through drunkenness or poisoning)}}, they will only think they have it, similar to the Drunk.","This does not apply to the Basement Cat themselves."],"howToRun":["When a Townsfolk dies at night, mark them with the **UNDEAD** reminder token.","Townsfolk with the **UNDEAD** reminder have their ability if the Basement Cat''s ability is in-play & active, or think they do if not.","Each dusk, remove all present **UNDEAD** reminder tokens from all players."],"quote":"Meoww meow meow meowwwwwww...","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"While setting up the game, before deciding on what character tokens to put in the bag, publicly announce what the Basement Cat''s █ variable will be for this game. This should be a standard unchanging number, write down the number on a piece of paper or on a phone.\n\nWhile preparing the first night, put the Basement Cat''s tail reminder tokens by them to indicate they have █ charges of the ability. Use the multiple **3 TAILS LEFT** reminder tokens to add up to a number you can then represent with a **1 TAIL LEFT** reminder token, or a **2 TAILS LEFT** reminder token.\n\nIf any non-Demon would die, they remain alive {{i|(but they die if you are drunk or poisoned)}}. If executed, declare that the player was executed but remains alive {{i|(do not say why)}}. Either way, a death was prevented - move around the different **TAIL(S) LEFT** reminder tokens to then equal the number it should be. Note that the Basement Cat counts twice, and thus you''ll be performing that operation twice.\n\nIf any non-Demon player dies for whatever reason, declare that the game ends and evil wins.\n\n**Basement Cat █~** (Townsfolk)\nThe 1st through █th time a non-Demon would die, they don''t (you count twice). If 1 actually dies, evil wins. [█ is known before setup]\n\n**Reminders:** 1 tail left, 2 tails left, 3 tails left, 3 tails left, 3 tails left\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nAssassin: The Assassin''s kill will fail unless it is the Basement Cat.\nAbdominal: The Abdominal cannot be protected by the Basement Cat.\nPeanut: The Peanut''s kill will fail unless it is the Basement Cat.\nProsecutor: The Prosecutor''s kill will fail unless it is the Basement Cat.\nLettucbaken: The Lettucbaken''s setup effect blocking does not affect the Basement Cat''s pre-game setup effect.\nActor: The Actor cannot drunken the Basement Cat."}],"firstNight":0,"otherNight":0,"remindersGlobal":["Undead","Undead","Undead","Undead","Undead"],"setup":false,"art":"art/basement-cat.png","jsonId":"basementcat_scp_fragmented_veil","curata":false}','scp-fragmented-veil/basement-cat','published',datetime('now'),datetime('now'));
